sources.python/job.py:
def pages(runs):
    return sum(runs)


def sheets(n, capacity):
    return (n + capacity - 1) // capacity

sources.python/colour.py:
from job import pages, sheets


def colour_total(jobs):
    count = sum(pages(job["colour"]) for job in jobs)
    return sheets(count, 4)

sources.python/mono.py:
from job import sheets


def mono_total(jobs):
    return sum(sheets(n, 3) for job in jobs for n in job["mono"])

